"use client";

import { useEffect, useRef, useState } from "react";

// The field guide's research time trial (Fig 9.1), embedded from public/lab/research-track.html
// (generated by scripts/lab-figure/embed.mjs). The page reports its own height.
export function LabResearchFigure() {
  const frame = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState<number | null>(null);
  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      if (event.source !== frame.current?.contentWindow) return;
      const data = event.data as { hitlFigure?: string; height?: number };
      if (data?.hitlFigure === "research-track" && typeof data.height === "number") setHeight(Math.ceil(data.height));
    };
    window.addEventListener("message", onMessage);
    // The frame may have loaded before this page hydrated; ask once now as well.
    frame.current?.contentWindow?.postMessage({ hitlFigure: "ping" }, "*");
    return () => window.removeEventListener("message", onMessage);
  }, []);
  const ask = () => frame.current?.contentWindow?.postMessage({ hitlFigure: "ping" }, "*");
  return <iframe ref={frame} className="v2-lab-figure" src="/lab/research-track.html" loading="lazy" onLoad={ask}
    title="Interactive drawing: a four-lane time trial where four experiments run at once, judged by a harness the agents can't touch"
    style={height ? { height } : undefined} />;
}
